def test_single_masked():
    assert solution.masked_nll([-0.5, -2.0], [1, 0]) == 0.5

def test_mean_over_masked():
    assert abs(solution.masked_nll([-0.1, -0.2, -0.3], [1, 1, 0]) - 0.15) < 1e-12

def test_unmasked_positions_ignored():
    got = solution.masked_nll([-0.1, -9.0, -0.3], [True, False, True])
    assert abs(got - 0.2) < 1e-12

def test_length_mismatch():
    try:
        solution.masked_nll([-0.1, -0.2], [1])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_no_masked_raises():
    try:
        solution.masked_nll([-0.1, -0.2], [0, 0])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.masked_nll([-0.5], [1]), float)
